// «В сети» — из присутствия агентов (Valkey): массивы online_club_ids/online_counts.
func (q *Queries) SuperadminClubs(ctx context.Context, arg SuperadminClubsParams) ([]SuperadminClubsRow, error) {
	rows, err := q.db.Query(ctx, superadminClubs,
		arg.Subscription,
		arg.Sort,
		arg.Direction,
		arg.PageOffset,
		arg.PageSize,
		arg.OnlineClubIds,
		arg.OnlineCounts,
		arg.Now,
		arg.LoadFrom,
		arg.DayAgo,
		arg.Search,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []SuperadminClubsRow
	for rows.Next() {
		var i SuperadminClubsRow
		if err := rows.Scan(
			&i.ID,
			&i.Name,
			&i.Slug,
			&i.CreatedAt,
			&i.OwnerName,
			&i.ComputersCount,
			&i.OnlineCount,
			&i.BusyCount,
			&i.AgentRequests,
			&i.ApiRequests,
			&i.LastLoginAt,
			&i.SessionsToday,
			&i.WebhookFailures,
			&i.SubscriptionID,
			&i.SubscriptionStatus,
			&i.TrialEndsAt,
			&i.CurrentPeriodEndsAt,
			&i.SubscriptionEndsAt,
			&i.SubscriptionActive,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

